            if match >= k:
                return True
            return num[i + match] <= num[j + match]

        dp = [[0] * (n + 1) for _ in range(n + 1)]
        for l in range(1, n + 1):
            dp[0][l] = 1

        for i in range(1, n + 1):
            for l in range(1, i + 1):
