                    if start >= l and cmp(start - l, start, l):
                        res = (res + dp[start][l] - dp[start][l - 1]) % MOD
                    dp[i][l] = (dp[i][l - 1] + res) % MOD
                else:
                    dp[i][l] = dp[i][l - 1]

