class Solution {
public:
    int numberOfCombinations(string num) {
        if (num[0] == '0') return 0;
        int n = num.size();
        const int MOD = 1e9 + 7;

        vector<vector<short>> lcp(n + 1, vector<short>(n + 1, 0));
        for (int i = n - 1; i >= 0; i--) {
            for (int j = n - 1; j >= 0; j--) {
                if (num[i] == num[j]) lcp[i][j] = 1 + lcp[i + 1][j + 1];
            }
        }

        auto cmp = [&](int i, int j, int k) -> bool {
            int match = lcp[i][j];
            if (match >= k) return true;
            return num[i + match] <= num[j + match];
        };

        vector<vector<int>> dp(n + 1, vector<int>(n + 1, 0));
        for (int l = 1; l <= n; l++) dp[0][l] = 1;

        for (int i = 1; i <= n; i++) {
            for (int l = 1; l <= i; l++) {
                int start = i - l;
                if (num[start] != '0') {
                    int res = dp[start][min(l - 1, start)];
                    if (start >= l && cmp(start - l, start, l)) {
                        int diff = (dp[start][l] - dp[start][l - 1] + MOD) % MOD;
                        res = (res + diff) % MOD;
                    }
                    dp[i][l] = (dp[i][l - 1] + res) % MOD;
                } else {
                    dp[i][l] = dp[i][l - 1];
                }
            }
            for (int l = i + 1; l <= n; l++) dp[i][l] = dp[i][i];
        }
        return dp[n][n];
    }
};

class Solution {
    public int numberOfCombinations(String num) {
        if (num.charAt(0) == '0') return 0;
        int n = num.length();
        final int MOD = 1_000_000_007;

        short[][] lcp = new short[n + 1][n + 1];
        for (int i = n - 1; i >= 0; i--) {
            for (int j = n - 1; j >= 0; j--) {
                if (num.charAt(i) == num.charAt(j)) lcp[i][j] = (short)(1 + lcp[i + 1][j + 1]);
            }
        }

        int[][] dp = new int[n + 1][n + 1];
        for (int l = 1; l <= n; l++) dp[0][l] = 1;

        for (int i = 1; i <= n; i++) {
            for (int l = 1; l <= i; l++) {
                int start = i - l;
                if (num.charAt(start) != '0') {
                    int res = dp[start][Math.min(l - 1, start)];
                    if (start >= l) {
                        int match = lcp[start - l][start];
                        boolean ok = (match >= l) || (num.charAt(start - l + match) <= num.charAt(start + match));
                        if (ok) {
                            int diff = (dp[start][l] - dp[start][l - 1] + MOD) % MOD;
                            res = (res + diff) % MOD;
                        }
                    }
                    dp[i][l] = (dp[i][l - 1] + res) % MOD;
                } else {
                    dp[i][l] = dp[i][l - 1];
                }
            }
            for (int l = i + 1; l <= n; l++) dp[i][l] = dp[i][i];
        }
        return dp[n][n];
    }
}

var numberOfCombinations = function(num) {
  if (num[0] === '0') return 0;
  const n = num.length;
  const MOD = 1000000007;

  const lcp = Array.from({ length: n + 1 }, () => new Int16Array(n + 1));
  for (let i = n - 1; i >= 0; i--) {
    for (let j = n - 1; j >= 0; j--) {
      if (num[i] === num[j]) lcp[i][j] = 1 + lcp[i + 1][j + 1];
    }
  }

  const cmp = (i, j, k) => {
    const match = lcp[i][j];
    if (match >= k) return true;
    return num[i + match] <= num[j + match];
  };

  const dp = Array.from({ length: n + 1 }, () => new Int32Array(n + 1));
  for (let l = 1; l <= n; l++) dp[0][l] = 1;

  for (let i = 1; i <= n; i++) {
    for (let l = 1; l <= i; l++) {
      const start = i - l;
      if (num[start] !== '0') {
        let res = dp[start][Math.min(l - 1, start)];
        if (start >= l && cmp(start - l, start, l)) {
          const diff = (dp[start][l] - dp[start][l - 1] + MOD) % MOD;
          res = (res + diff) % MOD;
        }
        dp[i][l] = (dp[i][l - 1] + res) % MOD;
      } else {
        dp[i][l] = dp[i][l - 1];
      }
    }
    for (let l = i + 1; l <= n; l++) dp[i][l] = dp[i][i];
  }
  return dp[n][n];
};
